// Public site URL used for canonical links, sitemap, robots and social previews.
// Social apps can only fetch the share image from a public URL, so set
// NEXT_PUBLIC_SITE_URL in production (e.g. https://yogalifekolkata.com).
// On Vercel the production domain is picked up automatically.
const vercelUrl = process.env.VERCEL_PROJECT_PRODUCTION_URL;
export const siteUrl = (
  process.env.NEXT_PUBLIC_SITE_URL ?? (vercelUrl ? `https://${vercelUrl}` : "http://localhost:3000")
).replace(/\/$/, "");

export const siteName = "Yogalife Kolkata";

// Default share card generated by app/opengraph-image.tsx.
export const defaultShareImage = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  type: "image/png",
  alt: "Yogalife Kolkata | Yoga, Naturopathy & Ayurveda in Kolkata",
};

// Pages that set their own openGraph replace the root one, so they spread this in.
// The image is listed explicitly so og:image is always in the HTML.
export const openGraphBase = {
  locale: "en_IN",
  siteName,
  images: [defaultShareImage],
};
